const items = $input.all();
if (items.length > 0) return items;
return [{ json: {
  documentId: '__wf02_empty_processed_placeholder__',
  lastProcessedDate: '',
  cycleId: ''
} }];

const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const description = '<p><strong>Source document:</strong> <a href="' + esc($json.docUrl) + '" target="_blank" rel="noopener noreferrer">' + esc($json.docName) + '</a></p>' + '<p><strong>Cycle:</strong> ' + esc($json.cycle_id) + '</p>' + '<p><strong>Validation:</strong> use the approval links in the first task comment.</p>' + '<p>Rule: move to Done only when both stamps are APPROVED.</p>';
// create_task_in_project: numeric project_id, plain strings (see SPEC.technical.md §12.3 — exo-mips-ft project 2).
return { ...$json, createTaskInput: { project_id: Number($vars.WF02_PROJECT_ID || 2), title: $json.title, description, assignee: $json.author_username, priority: 'NORMAL' } };

const parse = $('Parse Approval').first();
if (!parse || !parse.json) {
  return [{ json: {} }];
}
const pa = parse.json;
const cycleKey = String(pa.cycleKey ?? '');
const rows = $('Get Approval Rows').all();
let found = {};
for (let i = 0; i < rows.length; i++) {
  const j = rows[i].json || {};
  if (String(j.cycleKey ?? '') === cycleKey) {
    found = j;
    break;
  }
}
const role = String(pa.role ?? '');
const now =
  typeof $now !== 'undefined' && typeof $now.toISO === 'function'
    ? $now.toISO()
    : new Date().toISOString();

let artistic_decision = String(found.artistic_decision ?? 'PENDING');
let artistic_reason = String(found.artistic_reason ?? '');
let artistic_at = String(found.artistic_at ?? '');
let technical_decision = String(found.technical_decision ?? 'PENDING');
let technical_reason = String(found.technical_reason ?? '');
let technical_at = String(found.technical_at ?? '');

if (role === 'artistic') {
  artistic_decision = String(pa.decision ?? 'PENDING');
  artistic_reason = String(pa.reason ?? '');
  artistic_at = now;
}
if (role === 'technical') {
  technical_decision = String(pa.decision ?? 'PENDING');
  technical_reason = String(pa.reason ?? '');
  technical_at = now;
}

return [
  {
    json: {
      cycleKey: pa.cycleKey,
      task_id: Number(pa.task_id),
      cycle_id: String(pa.cycle_id ?? ''),
      document_id: String(found.document_id ?? ''),
      author_username: String(found.author_username ?? 'claire'),
      artistic_decision,
      artistic_reason,
      artistic_at,
      technical_decision,
      technical_reason,
      technical_at,
    },
  },
];
